package io.github.polestarcn.companion;
import static org.junit.Assert.*;
import android.content.*;import android.graphics.*;import android.location.Address;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.time.Duration;import java.util.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,qualifiers="w360dp-h780dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class UiV095Test {
 @Before public void clear(){RuntimeEnvironment.getApplication().getSharedPreferences("preferences",0).edit().clear().commit();}
 @Test public void vehicleHoldRequiresOnePointOneSecondsAndDoesNotClickAfterward(){Context c=RuntimeEnvironment.getApplication();VehicleHeroView v=new VehicleHeroView(c,true);int[] events={0,0};v.setVehicleHold(()->events[0]++);v.setOnClickListener(view->events[1]++);v.onTouchEvent(MotionEvent.obtain(0,0,MotionEvent.ACTION_DOWN,20,20,0));Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(1099));assertEquals(0,events[0]);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(1));assertEquals(1,events[0]);v.onTouchEvent(MotionEvent.obtain(0,1100,MotionEvent.ACTION_UP,20,20,0));assertEquals(0,events[1]);v.onTouchEvent(MotionEvent.obtain(4000,4000,MotionEvent.ACTION_DOWN,20,20,0));v.onTouchEvent(MotionEvent.obtain(4000,4100,MotionEvent.ACTION_MOVE,120,20,0));Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(3100));assertEquals(1,events[0]);}
 @Test public void placeNamesDoNotPresentCoordinatesAsAddress(){Address a=new Address(Locale.CHINA);a.setAddressLine(0,"23.00000, 113.00000");assertEquals("",ParkingPlaceNames.label(a));a.setSubLocality("南山区");a.setThoroughfare("科技南路");assertTrue(ParkingPlaceNames.label(a).contains("科技南路"));assertFalse(ParkingPlaceNames.label(a).contains("113.00000"));}
 @Test public void noParkingPointNeverRendersCoordinatesOrPretendsToHaveAName(){Context c=RuntimeEnvironment.getApplication();AppPreferences.set(c,"language","zh");assertEquals("停车数据未更新",ParkingPlaceNames.caption(c,null,"old name"));java.util.Map<Integer,Object> point=new java.util.HashMap<>();point.put(1,113.12345d);point.put(2,23.12345d);java.util.Map<Integer,Object> reply=new java.util.HashMap<>();reply.put(2,io.github.polestarcn.companion.api.ProtoWire.concat(io.github.polestarcn.companion.api.ProtoWire.fixed32Field(1,113.125f),io.github.polestarcn.companion.api.ProtoWire.fixed32Field(2,23.125f)));LocationSnapshot p=LocationSnapshot.fromReply(reply);assertNotNull(p);assertEquals("23.12500, 113.12500",ParkingPlaceNames.caption(c,p,""));assertEquals("科技南路",ParkingPlaceNames.caption(c,p,"科技南路"));}
 @Test public void connectionNeedsFreshReadNotJustSavedSession(){long now=System.currentTimeMillis();VehicleSnapshot state=new VehicleSnapshot("fixture","masked",50,200,100,"空闲","全部关闭","全部关闭","已关闭","已上锁",now,"LIVE",false);assertFalse(VehicleConnectionStatus.connected(true,true,false,state,now));assertFalse(VehicleConnectionStatus.connected(false,true,true,state,now));assertFalse(VehicleConnectionStatus.connected(true,true,true,state,now+900001));assertTrue(VehicleConnectionStatus.connected(true,true,true,state,now));}
 @Test public void allCarSelectionsApplyToDefaultAndSimple2(){Context c=RuntimeEnvironment.getApplication();AppPreferences.set(c,"theme","light");for(String skin:new String[]{UiSkin.PS_DEFAULT,UiSkin.SIMPLE_2}){UiSkin.set(c,skin);for(String key:VehicleArt.KEYS){if("auto".equals(key))continue;AppPreferences.set(c,"vehicle_art_day",key);assertEquals(key,VehicleArt.drawable(key,false,false,false),VehicleArt.dashboard(c));}}}
 @Test public void airAndWindowRenderersSupportBothDirectionsEveryColor(){Context c=RuntimeEnvironment.getApplication();for(String direction:new String[]{"through","absorb"}){AppPreferences.set(c,"fx_air_direction",direction);for(EffectStateController.Mode mode:new EffectStateController.Mode[]{EffectStateController.Mode.HEATING,EffectStateController.Mode.COOLING,EffectStateController.Mode.PURIFICATION}){Bitmap b=Bitmap.createBitmap(500,300,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);new AirflowRenderer().draw(canvas,new RectF(40,40,460,260),true,2,1,new EffectSettings(c),mode,120,1);int[] pixels=new int[500*300];b.getPixels(pixels,0,500,0,0,500,300);int n=0;for(int value:pixels)if(Color.alpha(value)>0)n++;assertTrue(n>100);b.eraseColor(0);new WindowGlowRenderer().draw(canvas,new RectF(0,0,500,300),R.drawable.vehicle_top,2,mode,100);assertEquals("roof stays clear",0,Color.alpha(b.getPixel(250,150)));assertEquals("outside stays clear",0,Color.alpha(b.getPixel(5,5)));b.recycle();}}}
 private MainActivity fixture(AppRegressionTest base)throws Exception{base.start();Field f=AppRegressionTest.class.getDeclaredField("activity");f.setAccessible(true);MainActivity a=(MainActivity)f.get(base);VehicleCoordinator m=VehicleCoordinator.get(a);Field signed=VehicleCoordinator.class.getDeclaredField("signedIn");signed.setAccessible(true);signed.setBoolean(m,true);m.selected=new io.github.polestarcn.companion.api.ChinaPolestarApi.VehicleInfo();m.selected.vin="TEST-V095";m.snapshot=new VehicleSnapshot("Polestar 2","masked",78,312,12000,"空闲","全部关闭","全部关闭","已关闭","已上锁",System.currentTimeMillis(),"LIVE",false,"关闭","关闭");AppPreferences.set(a,"home_metrics","odometer,ta_consumption,aqi");return a;}
 private void render(MainActivity a)throws Exception{Method r=MainActivity.class.getDeclaredMethod("render");r.setAccessible(true);r.invoke(a);View root=a.getWindow().getDecorView();root.measure(View.MeasureSpec.makeMeasureSpec(360,1073741824),View.MeasureSpec.makeMeasureSpec(780,1073741824));root.layout(0,0,360,780);}
 @Test public void everySkinUsesSameHealthSlotForChargingAndKeepsControls()throws Exception{AppRegressionTest base=new AppRegressionTest();MainActivity a=fixture(base);VehicleCoordinator m=VehicleCoordinator.get(a);try{for(String skin:UiSkin.pickerChoices()){UiSkin.set(a,skin);render(a);View root=a.getWindow().getDecorView();View health=root.findViewWithTag("vehicle_status_button");assertNotNull(skin,health);assertEquals(View.VISIBLE,health.getVisibility());m.snapshot=new VehicleSnapshot("Polestar 2","masked",78,312,12000,"充电中","全部关闭","全部关闭","已关闭","已上锁",System.currentTimeMillis(),"LIVE",false,"关闭","关闭");Method changed=MainActivity.class.getDeclaredMethod("onModelChanged");changed.setAccessible(true);changed.invoke(a);assertEquals(skin,View.GONE,health.getVisibility());assertNotNull(root.findViewWithTag("bottom_nav"));m.snapshot=new VehicleSnapshot("Polestar 2","masked",78,312,12000,"空闲","全部关闭","全部关闭","已关闭","已上锁",System.currentTimeMillis(),"LIVE",false,"关闭","关闭");}}finally{base.stop();}}
 @Test public void exportSimple2DayNightAndSettings()throws Exception{AppRegressionTest base=new AppRegressionTest();MainActivity a=fixture(base);try{UiSkin.set(a,UiSkin.SIMPLE_2);for(String theme:new String[]{"light","dark"}){AppPreferences.set(a,"theme",theme);render(a);save(a,"simple2-"+theme);AppPreferences.set(a,"all_good_position","behind");render(a);save(a,"simple2-behind-"+theme);AppPreferences.set(a,"all_good_lines","two");render(a);save(a,"simple2-behind-two-"+theme);AppPreferences.set(a,"all_good_lines","one");AppPreferences.set(a,"all_good_position","below");}Field page=MainActivity.class.getDeclaredField("page");page.setAccessible(true);page.setInt(a,2);render(a);save(a,"settings-dark");}finally{base.stop();}}
 private void save(MainActivity a,String name)throws Exception{Bitmap b=Bitmap.createBitmap(720,1560,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.scale(2,2);a.getWindow().getDecorView().draw(c);File f=new File("build/reports/previews/v095/"+name+".png");f.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
}
